  1437	    if (!view || !out || !n || cap < 2) {
  1438	        return;
  1439	    }
  1440	    if (!vmap_view_geo_to_canvas_raw(view, lon, lat, &x, &y)) {
  1441	        return;
  1442	    }
  1443	    if (!vmap_view_canvas_point_in_pad(view, x, y, 64)) {
  1444	        return;
  1445	    }
  1446	
  1447	    if (*n > 0) {
  1448	        const int32_t px = out[*n - 1].x;
  1449	        const int32_t py = out[*n - 1].y;
  1450	
  1451	        if (!route_px_keep(px, py, x, y, force || (*n + 1 >= cap))) {
  1452	            return;
  1453	        }
  1454	
  1455	        vmap_view_get_buffer_size(view, &cw, &ch);
  1456	        max_jump2 = (int64_t)(cw > ch ? cw : ch);
  1457	        max_jump2 *= max_jump2;
  1458	        {
  1459	            const int64_t dx = (int64_t)x - (int64_t)px;
  1460	            const int64_t dy = (int64_t)y - (int64_t)py;
  1461	
  1462	            if (dx * dx + dy * dy > max_jump2) {
  1463	                return;
  1464	            }
  1465	        }
  1466	    }
