  1468	    if (*n >= cap) {
  1469	        out[cap - 1].x = x;
  1470	        out[cap - 1].y = y;
  1471	        return;
  1472	    }
  1473	    out[*n].x = x;
  1474	    out[*n].y = y;
  1475	    (*n)++;
