  1483	#define VMAP_ROUTE_CHEVRON_STEP_M  250.0
  1484	#define VMAP_ROUTE_CHEVRON_MAX     24
  1485	#define VMAP_ROUTE_CHEVRON_ARM_PX  8
  1486	#define VMAP_ROUTE_CHEVRON_DEG     44.0
  1487	
  1488	/** @brief 沿屏幕方向画一个黑色 "^"：两臂各偏 ±35°、长 5 px、线宽 2。 */
  1489	/**
  1490	 * @brief 方向指示（"^" 瓦片）的颜色：日光=**黑**（一直是这个），夜间=**橙**。
  1491	 *
  1492	 * @note 用户 2026-09-27 定：黑的 ^ 在夜间那份深色地图上完全看不见 ⇒ 夜间改橙 #FF6E12
  1493	 *       （RGB565 0xFB62）；日光保持原来的黑（浅色底上黑最清楚，也不必和蓝色路线较劲）。
  1494	 *       判据与路线取色同源（地图风格，night = 夜间）。
  1495	 * @return RGB565。
  1496	 */
  1497	static uint16_t route_chevron_rgb(void)
  1498	{
  1499	    return (vmap_style_get_id() == VMAP_STYLE_NIGHT) ? (uint16_t)0xFB62u
  1500	                                                      : (uint16_t)0x0000u;
  1501	}
  1502	
  1503	static void route_draw_chevron(vmap_canvas_t * canvas, int32_t x, int32_t y,
  1504	    double ang_rad)
  1505	{
  1506	    const double half = VMAP_ROUTE_CHEVRON_DEG * (3.14159265358979323846 / 180.0);
  1507	    int s;
  1508	
  1509	    for (s = -1; s <= 1; s += 2) {
  1510	        const double a = ang_rad + 3.14159265358979323846 + (double)s * half;
  1511	        vmap_point_t arm[2];
  1512	
  1513	        arm[0].x = x;
  1514	        arm[0].y = y;
  1515	        arm[1].x = (int32_t)((double)x + cos(a) * VMAP_ROUTE_CHEVRON_ARM_PX + 0.5);
  1516	        arm[1].y = (int32_t)((double)y + sin(a) * VMAP_ROUTE_CHEVRON_ARM_PX + 0.5);
  1517	        /* 方向指示（"^"）：日光黑、夜间橙 —— 见 route_chevron_rgb() 的注释。 */
  1518	        vmap_render_stroke_ribbon(canvas, arm, 2, 2, route_chevron_rgb());
  1519	    }
  1520	}
