  1537	/* —— 路线/箭头的擦除记账 ——
  1538	 * 覆盖层是烘进常驻画布的：瓦片重贴会盖掉线（该补画），但**几何跳变**（GPX 窗口续载、
  1539	 * 跟车重锚、容器尺寸变化）会让旧位置的墨迹没人擦，留下残影（用户 2026-09-25 实测：
  1540	 * "每进一次地图就多烘一份"）。做法与路名标注一致：记下这一帧画过的屏幕框与分割点，
  1541	 * 下一次发现分割点**跳变**就把旧框并进脏区，让瓦片在那儿重贴一遍。
  1542	 * 只在跳变时发生（不是每拍），所以代价可控。 */
  1543	static lv_area_t s_route_box;
  1544	static int32_t   s_route_split_x;
  1545	static int32_t   s_route_split_y;
  1546	static bool      s_route_box_valid;
  1547	
  1548	static void route_note_box(lv_area_t * box, int32_t x1, int32_t y1, int32_t x2,
  1549	    int32_t y2)
  1550	{
  1551	    if (x1 > x2) {
  1552	        const int32_t t = x1;
  1553	
  1554	        x1 = x2;
  1555	        x2 = t;
  1556	    }
  1557	    if (y1 > y2) {
  1558	        const int32_t t = y1;
  1559	
  1560	        y1 = y2;
  1561	        y2 = t;
  1562	    }
  1563	    box->x1 = (box->x1 < x1) ? box->x1 : x1;
  1564	    box->y1 = (box->y1 < y1) ? box->y1 : y1;
  1565	    box->x2 = (box->x2 > x2) ? box->x2 : x2;
  1566	    box->y2 = (box->y2 > y2) ? box->y2 : y2;
  1567	}
