  1569	static void route_paint_geo_range(const vmap_view_t * view, vmap_canvas_t * canvas,
  1570	    const vmap_route_pt_t * pts, const float * along, uint32_t begin, uint32_t end,
  1571	    double extra_lon, double extra_lat, double extra_along, bool extra_first,
  1572	    uint16_t rgb565)
  1573	{
  1574	    vmap_point_t px[256];
  1575	    vmap_point_t chev[VMAP_ROUTE_CHEVRON_MAX];
  1576	    double chev_ang[VMAP_ROUTE_CHEVRON_MAX];
  1577	    int32_t chev_n = 0;
  1578	    double prev_along = 0.0;
  1579	    double next_mark = 0.0;
  1580	    int32_t start_x = 0;
  1581	    int32_t start_y = 0;
  1582	    int32_t n = 0;
  1583	    uint32_t i;
  1584	
  1585	    if (!view || !canvas || !pts || end < 2u || begin + 1u > end) {
  1586	        return;
  1587	    }
  1588	
  1589	    lv_area_t new_box = { INT32_MAX, INT32_MAX, INT32_MIN, INT32_MIN };
  1590	    const bool chevrons = extra_first && along != NULL;
  1591	
  1592	    if (extra_first) {
  1593	        route_append_geo(view, px, &n, (int32_t)(sizeof(px) / sizeof(px[0])),
  1594	            extra_lon, extra_lat, true);
  1595	        if (n > 0) {
  1596	            /* 分块落线会覆盖 px[0]；骑手投影点先单独留一份给跳变记账。 */
  1597	            start_x = px[0].x;
  1598	            start_y = px[0].y;
  1599	        }
  1600	    }
  1601	
  1602	    if (chevrons) {
  1603	        prev_along = extra_along;
  1604	        next_mark = ceil(prev_along / VMAP_ROUTE_CHEVRON_STEP_M)
  1605	            * VMAP_ROUTE_CHEVRON_STEP_M;
  1606	        if (next_mark <= prev_along) {
  1607	            next_mark += VMAP_ROUTE_CHEVRON_STEP_M;
  1608	        }
  1609	    } else if (along != NULL && begin > 0u) {
  1610	        prev_along = (double)along[begin - 1u];
  1611	    }
  1612	
  1613	    for (i = begin; i < end; i++) {
  1614	        const bool last = (i + 1u == end);
  1615	        const int32_t before = n;
  1616	
  1617	        route_append_geo(view, px, &n, (int32_t)(sizeof(px) / sizeof(px[0])),
  1618	            pts[i].lon, pts[i].lat, last);
  1619	
  1620	        if (n > before && n >= 2) {
  1621	            const int32_t k = n - 1;
  1622	            const double dx = (double)(px[k].x - px[k - 1].x);
  1623	            const double dy = (double)(px[k].y - px[k - 1].y);
  1624	            const double seg_m = (along != NULL) ? (double)along[i] - prev_along
  1625	                                                 : 0.0;
  1626	
  1627	            /* ^ 按沿路线里程取（不是点序号）：稀疏 GPX / 路网路线点距变化很大，
  1628	             * 点序号会把 ^ 拉成几百米一个；里程基准与绘制起点无关，重绘幂等。 */
  1629	            if (chevrons && along != NULL) {
  1630	                while (chev_n < VMAP_ROUTE_CHEVRON_MAX
  1631	                    && next_mark <= (double)along[i]) {
  1632	                    double t = (seg_m > 0.0)
  1633	                        ? (next_mark - prev_along) / seg_m : 1.0;
  1634	
  1635	                    if (t < 0.0) {
  1636	                        t = 0.0;
  1637	                    } else if (t > 1.0) {
  1638	                        t = 1.0;
  1639	                    }
  1640	                    chev[chev_n].x = px[k - 1].x + (int32_t)lround(dx * t);
  1641	                    chev[chev_n].y = px[k - 1].y + (int32_t)lround(dy * t);
  1642	                    chev_ang[chev_n] = atan2(dy, dx);
  1643	                    chev_n++;
  1644	                    next_mark += VMAP_ROUTE_CHEVRON_STEP_M;
  1645	                }
  1646	            }
  1647	            if (along != NULL) {
  1648	                prev_along = (double)along[i];
  1649	            }
  1650	            route_note_box(&new_box, px[k - 1].x, px[k - 1].y, px[k].x, px[k].y);
  1651	
  1652	            /* px 满之前先落一遍线，末点留作下一块的首点：route_append_geo 在
  1653	             * 满容量时会覆盖末点，旧 ^ 会悬在已被替换的线段上。 */
  1654	            if (n >= (int32_t)(sizeof(px) / sizeof(px[0])) && i + 1u < end) {
  1655	                route_stroke_px(canvas, px, n, rgb565);
  1656	                px[0] = px[n - 1];
  1657	                n = 1;
  1658	            }
  1659	        }
  1660	    }
  1661	
  1662	    route_stroke_px(canvas, px, n, rgb565);
  1663	
  1664	    /* ^ 画在蓝线之后：黑/橙两臂压在蓝线上才看得清（原来先画线后画 ^，
  1665	     * 线把 ^ 的中心盖掉了）。 */
  1666	    for (i = 0; i < (uint32_t)chev_n; i++) {
  1667	        route_draw_chevron(canvas, chev[i].x, chev[i].y, chev_ang[i]);
  1668	        route_note_box(&new_box, chev[i].x - VMAP_ROUTE_CHEVRON_ARM_PX,
  1669	            chev[i].y - VMAP_ROUTE_CHEVRON_ARM_PX,
  1670	            chev[i].x + VMAP_ROUTE_CHEVRON_ARM_PX,
  1671	            chev[i].y + VMAP_ROUTE_CHEVRON_ARM_PX);
  1672	    }
  1673	
  1674	    if (extra_first && n >= 2) {
  1675	        /* 分割点跳变判定：以路线起点（骑手位置投影）为准，阈值取半个屏宽 ——
  1676	         * 小于它的移动都属于跟车滚动，滚动脏条已经覆盖。 */
  1677	        const int32_t sx = start_x;
  1678	        const int32_t sy = start_y;
  1679	        int32_t jx = sx - s_route_split_x;
  1680	        int32_t jy = sy - s_route_split_y;
  1681	
  1682	        if (jx < 0) {
  1683	            jx = -jx;
  1684	        }
  1685	        if (jy < 0) {
  1686	            jy = -jy;
  1687	        }
  1688	        if (s_route_box_valid && (jx > 120 || jy > 120)) {
  1689	            vmap_view_invalidate_canvas_area(view, s_route_box.x1, s_route_box.y1,
  1690	                s_route_box.x2, s_route_box.y2);
  1691	        }
  1692	        if (new_box.x2 >= new_box.x1) {
  1693	            s_route_box = new_box;
  1694	            s_route_box_valid = true;
  1695	        }
  1696	        s_route_split_x = sx;
  1697	        s_route_split_y = sy;
  1698	    }
  1699	}
